import './styles.css';
import { useState, useReducer, createContext, useContext, ReactNode } from 'react';

// ==========================================
// Approach 1: Simple useState
// ==========================================
function UseStateCounter() {
  const [count, setCount] = useState(0);

  return (
    <div className="counter-card">
      <h3>useState</h3>
      <p className="description">Simple local state</p>
      <div className="counter-display">{count}</div>
      <div className="button-group">
        <button onClick={() => setCount(c => c - 1)}>-</button>
        <button onClick={() => setCount(0)}>Reset</button>
        <button onClick={() => setCount(c => c + 1)}>+</button>
      </div>
    </div>
  );
}

// ==========================================
// Approach 2: useReducer
// ==========================================
type Action = 
  | { type: 'INCREMENT' }
  | { type: 'DECREMENT' }
  | { type: 'RESET' }
  | { type: 'SET'; payload: number };

function reducer(state: number, action: Action): number {
  switch (action.type) {
    case 'INCREMENT': return state + 1;
    case 'DECREMENT': return state - 1;
    case 'RESET': return 0;
    case 'SET': return action.payload;
    default: return state;
  }
}

function UseReducerCounter() {
  const [count, dispatch] = useReducer(reducer, 0);

  return (
    <div className="counter-card">
      <h3>useReducer</h3>
      <p className="description">Predictable state updates</p>
      <div className="counter-display">{count}</div>
      <div className="button-group">
        <button onClick={() => dispatch({ type: 'DECREMENT' })}>-</button>
        <button onClick={() => dispatch({ type: 'RESET' })}>Reset</button>
        <button onClick={() => dispatch({ type: 'INCREMENT' })}>+</button>
      </div>
    </div>
  );
}

// ==========================================
// Approach 3: Context
// ==========================================
interface CounterContextValue {
  count: number;
  increment: () => void;
  decrement: () => void;
  reset: () => void;
}

const CounterContext = createContext<CounterContextValue | null>(null);

function CounterProvider({ children }: { children: ReactNode }) {
  const [count, setCount] = useState(0);

  const value: CounterContextValue = {
    count,
    increment: () => setCount(c => c + 1),
    decrement: () => setCount(c => c - 1),
    reset: () => setCount(0),
  };

  return (
    <CounterContext.Provider value={value}>
      {children}
    </CounterContext.Provider>
  );
}

function useCounter() {
  const context = useContext(CounterContext);
  if (!context) throw new Error('useCounter must be used within CounterProvider');
  return context;
}

function ContextDisplay() {
  const { count } = useCounter();
  return <div className="counter-display">{count}</div>;
}

function ContextControls() {
  const { increment, decrement, reset } = useCounter();
  return (
    <div className="button-group">
      <button onClick={decrement}>-</button>
      <button onClick={reset}>Reset</button>
      <button onClick={increment}>+</button>
    </div>
  );
}

function ContextCounter() {
  return (
    <CounterProvider>
      <div className="counter-card">
        <h3>Context</h3>
        <p className="description">Shared across components</p>
        <ContextDisplay />
        <ContextControls />
      </div>
    </CounterProvider>
  );
}

// ==========================================
// Main App
// ==========================================
export default function App() {
  return (
    <div className="app">
      <h1>State Management Patterns</h1>
      <p className="subtitle">
        Compare different approaches to managing state in React
      </p>

      <div className="counters-grid">
        <UseStateCounter />
        <UseReducerCounter />
        <ContextCounter />
      </div>

      <div className="info-box">
        <h4>When to use each:</h4>
        <ul>
          <li><strong>useState:</strong> Simple values in a single component</li>
          <li><strong>useReducer:</strong> Complex logic or multiple actions</li>
          <li><strong>Context:</strong> State needed by many components</li>
        </ul>
      </div>
    </div>
  );
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, sans-serif;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  min-height: 100vh;
  padding: 2rem 1rem;
}

.app {
  max-width: 900px;
  margin: 0 auto;
}

h1 {
  color: white;
  text-align: center;
  margin-bottom: 0.5rem;
}

.subtitle {
  color: rgba(255, 255, 255, 0.8);
  text-align: center;
  margin-bottom: 2rem;
}

.counters-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 1.5rem;
  margin-bottom: 2rem;
}

.counter-card {
  background: white;
  border-radius: 1rem;
  padding: 1.5rem;
  text-align: center;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.2);
}

.counter-card h3 {
  color: #1f2937;
  margin-bottom: 0.25rem;
}

.counter-card .description {
  color: #6b7280;
  font-size: 0.875rem;
  margin-bottom: 1rem;
}

.counter-display {
  font-size: 4rem;
  font-weight: bold;
  color: #667eea;
  margin: 1rem 0;
}

.button-group {
  display: flex;
  justify-content: center;
  gap: 0.5rem;
}

.button-group button {
  width: 50px;
  height: 50px;
  border: none;
  border-radius: 0.75rem;
  font-size: 1.25rem;
  font-weight: bold;
  cursor: pointer;
  transition: all 0.2s;
}

.button-group button:first-child {
  background: #fee2e2;
  color: #dc2626;
}

.button-group button:first-child:hover {
  background: #fecaca;
}

.button-group button:nth-child(2) {
  background: #f3f4f6;
  color: #6b7280;
  width: auto;
  padding: 0 1rem;
}

.button-group button:nth-child(2):hover {
  background: #e5e7eb;
}

.button-group button:last-child {
  background: #dcfce7;
  color: #16a34a;
}

.button-group button:last-child:hover {
  background: #bbf7d0;
}

.info-box {
  background: rgba(255, 255, 255, 0.95);
  border-radius: 1rem;
  padding: 1.5rem;
}

.info-box h4 {
  color: #1f2937;
  margin-bottom: 1rem;
}

.info-box ul {
  list-style: none;
}

.info-box li {
  padding: 0.5rem 0;
  color: #4b5563;
  border-bottom: 1px solid #f3f4f6;
}

.info-box li:last-child {
  border-bottom: none;
}

.info-box strong {
  color: #667eea;
}
